  `https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=${lawCode}&sectionNum=${sectionNum}`;

/** The Judicial Council's civil jury instructions, 2026 edition (one PDF; listed once per page). */
const caci = (numbers: string): PageSource => ({
  label: `Judicial Council of California, Civil Jury Instructions (CACI) ${/[,–]/.test(numbers) ? 'Nos.' : 'No.'} ${numbers} (2026 edition)`,
  url: 'https://courts.ca.gov/system/files/file/judicial_council_of_california_civil_jury_instructions_2026.pdf',
});

